/**
 * Errors that can cross the UniFFI boundary from the Swift adapters back into
 * the Rust engine. UniFFI requires every foreign-trait method to return
 * `Result<_, CompatibleError>`; this is the compatible error type.
 *
 * `Timeout` carries BLE-RT-C003 (IOS_DESIGN §4 / AC-6): the `gatt_read` path
 * in the Swift `IosBleAdapter` enforces a hard call-timeout (default 10 s) and
 * surfaces it here as a typed error — no hang, no leaked task.
 */
public enum IrisFfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case NotSupported
    case PermissionDenied
    case AdapterOff
    case DeviceNotFound
    case GattFailure(String
    )
    case Timeout
    case IoError(String
    )
    case InvalidArgument(String
    )
    case Transport(String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension IrisFfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeIrisFfiError: FfiConverterRustBuffer {
    typealias SwiftType = IrisFfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> IrisFfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotSupported
        case 2: return .PermissionDenied
        case 3: return .AdapterOff
        case 4: return .DeviceNotFound
        case 5: return .GattFailure(
            try FfiConverterString.read(from: &buf)
            )
        case 6: return .Timeout
        case 7: return .IoError(
            try FfiConverterString.read(from: &buf)
            )
        case 8: return .InvalidArgument(
            try FfiConverterString.read(from: &buf)
            )
        case 9: return .Transport(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: IrisFfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NotSupported:
            writeInt(&buf, Int32(1))
        
        
        case .PermissionDenied:
            writeInt(&buf, Int32(2))
        
        
        case .AdapterOff:
            writeInt(&buf, Int32(3))
        
        
        case .DeviceNotFound:
            writeInt(&buf, Int32(4))
        
        
        case let .GattFailure(v1):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .Timeout:
            writeInt(&buf, Int32(6))
        
        
        case let .IoError(v1):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .InvalidArgument(v1):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Transport(v1):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


