fileprivate struct FfiConverterSequenceTypeFfiGattWriteEvent: FfiConverterRustBuffer {
    typealias SwiftType = [FfiGattWriteEvent]

    public static func write(_ value: [FfiGattWriteEvent], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeFfiGattWriteEvent.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [FfiGattWriteEvent] {
        let len: Int32 = try readInt(&buf)
        var seq = [FfiGattWriteEvent]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeFfiGattWriteEvent.read(from: &buf))
        }
        return seq
    }
}

